WITH daily_sales AS (SELECT ss.ss_store_sk, ss.ss_sold_date_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(ss.ss_ext_sales_price) AS daily_sales_amount, SUM(ss.ss_quantity) AS daily_units_sold FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY ss.ss_store_sk, ss.ss_sold_date_sk, ib.ib_lower_bound, ib.ib_upper_bound), daily_returns AS (SELECT sr.sr_store_sk, sr.sr_returned_date_sk, ib.ib_lower_bound, ib.ib_upper_bound, SUM(sr.sr_return_amt) AS daily_return_amount, SUM(sr.sr_return_quantity) AS daily_return_qty FROM store_returns sr JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN income_band ib ON hd.hd_income_band_sk = ib.ib_income_band_sk GROUP BY sr.sr_store_sk, sr.sr_returned_date_sk, ib.ib_lower_bound, ib.ib_upper_bound) SELECT ds.ss_store_sk AS store_id, ds.ss_sold_date_sk AS date_key, ds.daily_sales_amount, dr.daily_return_amount, CASE WHEN ds.daily_sales_amount = 0 THEN NULL ELSE dr.daily_return_amount / ds.daily_sales_amount END AS return_to_sales_ratio, CASE WHEN dr.daily_return_amount > 5000 THEN 'High Return' ELSE 'Normal' END AS return_day_flag, SUM(dr.daily_return_amount) OVER (PARTITION BY ds.ss_store_sk ORDER BY ds.ss_sold_date_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amount, DENSE_RANK() OVER (PARTITION BY ds.ss_store_sk ORDER BY dr.daily_return_amount DESC) AS daily_return_rank FROM daily_sales ds LEFT JOIN daily_returns dr ON ds.ss_store_sk = dr.sr_store_sk AND ds.ss_sold_date_sk = dr.sr_returned_date_sk ORDER BY ds.ss_store_sk, ds.ss_sold_date_sk
